import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def min_mono_triangles(n):
    if n < 3:
        return 0
    # Find the closest partition n_R, n_B
    n_R = n // 2
    n_B = n - n_R

    return combinations(n_R, 3) + combinations(n_B, 3)

# Test small values of n
results = {}
for n in range(3, 11):
    results[n] = min_mono_triangles(n)
    print(f"n={n}: Minimum Monochromatic Triangles = {results[n]}")

# Find the smallest n >= 6 where the count is >= 2
guaranteed_n = next((n for n, count in results.items() if count >= 2), None)
print(f"Smallest n guaranteeing >= 2: {guaranteed_n}")

